<?php
namespace App\Modules\Scheduling\Actions;
use App\Modules\Scheduling\Models\{Appointment,AppointmentEvent,EventType}; use App\Modules\Scheduling\Notifications\AppointmentRescheduledNotification; use App\Modules\Scheduling\Services\{SchedulingAudit,SchedulingNotificationCenter,SlotGenerator}; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\{DB,Notification}; use Illuminate\Validation\ValidationException;
final class RescheduleAppointment { public function __construct(private SlotGenerator $slots,private SchedulingAudit $audit,private SchedulingNotificationCenter $notificationCenter){} public function execute(Appointment $appointment,string $token,string $start,string $timezone,?int $actor=null): array{$cancel=bin2hex(random_bytes(32));$reschedule=bin2hex(random_bytes(32));$item=DB::transaction(function()use($appointment,$token,$start,$timezone,$actor,$cancel,$reschedule){$type=EventType::query()->lockForUpdate()->findOrFail($appointment->event_type_id);$item=Appointment::query()->lockForUpdate()->findOrFail($appointment->id);if(!$actor&&!hash_equals($item->reschedule_token_hash,hash('sha256',$token)))throw ValidationException::withMessages(['token'=>'Link de reagendamento inválido.']);if(!in_array($item->status,['scheduled','confirmed'],true))throw ValidationException::withMessages(['start'=>'Este agendamento não pode ser reagendado.']);$date=CarbonImmutable::parse($start,$timezone);$oldStart=$item->scheduled_start_at;$ok=collect($this->slots->generate($type,$date->format('Y-m-d'),$timezone,null,$item->id))->contains('start',$date->toIso8601String());if(!$ok)throw ValidationException::withMessages(['start'=>'Este horário não está mais disponível.']);$item->update(['scheduled_start_at'=>$date->utc(),'scheduled_end_at'=>$date->addMinutes($type->duration_minutes)->utc(),'timezone'=>$timezone,'status'=>'confirmed','cancelled_at'=>null,'cancellation_token_hash'=>hash('sha256',$cancel),'reschedule_token_hash'=>hash('sha256',$reschedule)]);DB::table('scheduling_reminder_deliveries')->where('appointment_id',$item->id)->delete();$event=AppointmentEvent::query()->create(['appointment_id'=>$item->id,'event_type'=>'rescheduled','metadata'=>['previous_start'=>$oldStart->toIso8601String()],'actor_type'=>$actor?'user':'guest','actor_id'=>$actor,'created_at'=>now()]);$this->audit->record('appointment.rescheduled',$item->id,$actor,['previous_start'=>$oldStart->toIso8601String(),'new_start'=>$date->utc()->toIso8601String()]);$this->notificationCenter->publish($item,'rescheduled',$event->id);return$item;},3);Notification::route('mail',$item->guest_email)->notify(new AppointmentRescheduledNotification($item,$cancel,$reschedule));return ['appointment'=>$item,'cancel'=>$cancel,'reschedule'=>$reschedule];}}
